pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        address originalOwner = c.owner();
        vm.assume(newOwner != originalOwner);

        // Call setOwner from the original owner's perspective
        vm.prank(originalOwner);
        c.setOwner(newOwner);

        // The owner MUST have changed to newOwner
        assertTrue(c.owner() == newOwner);
    }
}

